// Fixed clock and fictional enquiries make the walkthrough repeatable.
const now = Date.parse('2026-11-20T06:30:00Z');
const leads = [
  {id: 'L101', owner: 'Priya', status: 'NEW', due: '2026-11-20T06:00:00Z'},
  {id: 'L102', owner: 'Ravi', status: 'NEW', due: '2026-11-20T08:00:00Z'},
  {id: 'L103', owner: 'Priya', status: 'CONTACTED', due: '2026-11-20T06:00:00Z'},
];

function reminderQueue(rows, asOf) {
  return rows.filter(lead => lead.status === 'NEW' && Date.parse(lead.due) <= asOf)
    .map(({id, owner, due}) => ({
      json: {id, owner, due, action: 'Owner to follow up', mode: 'demo'},
    }));
}

return reminderQueue(leads, now);
